                                 <button onClick={() => onMoveNestPart && onMoveNestPart(selectedNestPartId, 5, 0)} className="bg-gray-600 hover:bg-gray-500 p-1 rounded">►</button>
                                 <div></div>
                                 <button onClick={() => onMoveNestPart && onMoveNestPart(selectedNestPartId, 0, 5)} className="bg-gray-600 hover:bg-gray-500 p-1 rounded">▼</button>
                                 <div></div>
                             </div>
                         </div>
                    )}
                </div>
            )}
        </aside>
    );
};

import React from 'react';
import { NestResultSheet, PunchOp, Tool } from '../../types';
import { TrashIcon, PlayIcon, LayersIcon, TurretIcon } from '../Icons';

interface CAMSidebarPanelProps {
    activeSheet: NestResultSheet;
    tools: Tool[];
    onUpdateOps: (ops: PunchOp[]) => void;
}

export const CAMSidebarPanel: React.FC<CAMSidebarPanelProps> = ({ activeSheet, tools, onUpdateOps }) => {
    const ops = activeSheet.optimizedOps || [];

    // Группировка операций по инструментам (с учетом последовательности)
    const groupedOps: { toolId: string; ops: PunchOp[]; isToolChange: boolean }[] = [];
    ops.forEach((op, idx) => {
        if (idx === 0 || op.isToolChange) {
            groupedOps.push({ toolId: op.toolId, ops: [op], isToolChange: true });
        } else {
            groupedOps[groupedOps.length - 1].ops.push(op);
        }
    });

    const handleRemoveToolGroup = (index: number) => {
        const group = groupedOps[index];
        const newOps = ops.filter(op => !group.ops.includes(op));
        onUpdateOps(newOps);
    };

    const handleMoveGroup = (index: number, direction: 'up' | 'down') => {
        const newGroups = [...groupedOps];
        if (direction === 'up' && index > 0) {
            [newGroups[index], newGroups[index - 1]] = [newGroups[index - 1], newGroups[index]];
        } else if (direction === 'down' && index < newGroups.length - 1) {
            [newGroups[index], newGroups[index + 1]] = [newGroups[index + 1], newGroups[index]];
        }
        // Реконструируем плоский список операций
        const flattenedOps: PunchOp[] = [];
        newGroups.forEach(g => {
            g.ops.forEach((op, i) => {
                flattenedOps.push({ ...op, isToolChange: i === 0 });
            });
        });
        onUpdateOps(flattenedOps);
    };

    const handleResetOptimization = () => {
        if (confirm("Вы уверены, что хотите сбросить оптимизацию? Все ручные правки будут потеряны.")) {
            onUpdateOps([]);
            // App.tsx сбросит флаг isOptimized если массив пуст
        }
    };

    const handleAddReclamp = (afterIndex: number) => {
        // Логика вставки G190 (перехват)
        const newOps = [...ops];
        const reclampOp: PunchOp = {
            type: 'reclamp',
            toolId: 'SYSTEM',
            x: 0,
            y: activeSheet.height,
            rotation: 0,
            description: 'ПЕРЕХВАТ ЗАЖИМОВ'
        };
        newOps.splice(afterIndex + 1, 0, reclampOp);
        onUpdateOps(newOps);
    };

    return (
        <div className="flex flex-col h-full space-y-4">
            <div className="bg-blue-900/20 border border-blue-500/50 p-3 rounded-md">
                <p className="text-xs text-blue-300 font-bold uppercase mb-1">Статус: Оптимизировано</p>
                <p className="text-[10px] text-gray-400">Последовательность обработки зафиксирована. Вы можете изменять порядок инструментов или добавлять перехваты.</p>
            </div>

            <div className="flex-1 overflow-y-auto space-y-2 pr-1 custom-scrollbar">
                <h4 className="text-xs font-bold text-gray-500 uppercase tracking-wider pl-1">Очередь инструментов</h4>
                {groupedOps.map((group, idx) => {
                    const tool = tools.find(t => t.id === group.toolId);
                    return (
                        <div key={idx} className="bg-gray-800 border border-gray-600 rounded-md p-2 flex flex-col space-y-2">
                            <div className="flex justify-between items-center">
                                <div className="flex items-center space-x-2">
                                    <span className="bg-gray-700 text-yellow-400 font-mono text-[10px] px-1.5 py-0.5 rounded border border-gray-600">
                                        T{tool?.stationNumber || '?'}
                                    </span>
                                    <span className="text-xs font-bold text-gray-200 truncate max-w-[120px]" title={tool?.name}>
                                        {tool?.name}
                                    </span>
                                </div>
                                <div className="flex space-x-1">
                                    <button onClick={() => handleMoveGroup(idx, 'up')} className="p-1 hover:bg-gray-700 rounded text-gray-400">▲</button>
                                    <button onClick={() => handleMoveGroup(idx, 'down')} className="p-1 hover:bg-gray-700 rounded text-gray-400">▼</button>
                                    <button onClick={() => handleRemoveToolGroup(idx)} className="p-1 hover:bg-red-900/50 text-red-400 rounded">×</button>
                                </div>
                            </div>
                            <div className="flex justify-between text-[10px] text-gray-500 px-1">
                                <span>Ударов: {group.ops.length}</span>
                                <button 
                                    onClick={() => handleAddReclamp(ops.indexOf(group.ops[group.ops.length-1]))}
                                    className="text-blue-400 hover:underline"
                                >
                                    + Перехват
                                </button>
                            </div>
                        </div>
                    );
                })}
            </div>

            <div className="pt-4 border-t border-gray-600 space-y-2">
                <button 
                    onClick={handleResetOptimization}
                    className="w-full py-2 bg-red-900/30 hover:bg-red-900/50 text-red-300 text-xs rounded border border-red-900/50 transition-colors"
                >
                    Сбросить CAM данные
                </button>
                <div className="bg-gray-900/50 p-2 rounded text-[10px] text-gray-500 italic">
                    * Для изменения геометрии деталей или их расположения сначала сбросьте оптимизацию.
                </div>
            </div>
        </div>
    );
};

import React, { useState, useMemo } from 'react';
import { Tool, NestLayout, Part, PunchOp, ToolShape } from '../types';
import { ToolPreview } from './common/ToolDisplay';
