// FIX: Added exported nestingGenerator to resolve the "Module './services/nesting' has no exported member 'nestingGenerator'" error in App.tsx.
export async function* nestingGenerator(
    scheduledParts: ScheduledPart[],
    parts: Part[],
    tools: Tool[],
    settings: NestingSettings
): AsyncGenerator<NestingProgressUpdate> {
    const sheets: NestResultSheet[] = [];
    const totalToPlace = scheduledParts.reduce((sum, p) => sum + p.quantity, 0);
    let placedCount = 0;

    yield { sheets, progress: 0, status: 'Подготовка деталей...' };

    // 1. Bake parts (masks and extents)
    const bakedParts = new Map<string, BakedPart>();
    for (const sp of scheduledParts) {
        const part = parts.find(p => p.id === sp.partId);
        if (part && !bakedParts.has(part.id)) {
            bakedParts.set(part.id, bakePartFull(part, tools));
        }
    }

    // 2. Local queue of parts to place
    let itemsToPlace = scheduledParts.map(p => ({
        partId: p.partId,
        quantity: p.quantity,
        constraints: p.nesting
    })).filter(i => i.quantity > 0);

    // Sort by height descending (simple heuristic)
    itemsToPlace.sort((a, b) => {
        const partA = parts.find(p => p.id === a.partId)!;
        const partB = parts.find(p => p.id === b.partId)!;
        return partB.geometry.height - partA.geometry.height;
    });

    // 3. Select sheets
    const availableStocks = settings.availableSheets.filter(s => s.useInNesting && s.quantity > 0);
    if (availableStocks.length === 0) {
        throw new Error("Нет доступных листов для раскроя");
    }

    let stockIdx = 0;

    while (itemsToPlace.some(i => i.quantity > 0)) {
        const stock = availableStocks[stockIdx];
        if (!stock) break;

        const currentSheet: NestResultSheet = {
            id: generateId(),
            sheetName: `Лист ${sheets.length + 1}`,
            stockSheetId: stock.id,
            width: stock.width,
            height: stock.height,
            material: stock.material,
            thickness: stock.thickness,
            placedParts: [],
            usedArea: 0,
            scrapPercentage: 100,
            partCount: 0,
            quantity: 1
        };

        // Simple shelf packing algorithm implementation
        let shelfY = Math.ceil(Math.max(0, settings.sheetMarginBottom) / GRID_RES);
        let shelfH = 0;
        let shelfX = Math.ceil(Math.max(0, settings.sheetMarginLeft) / GRID_RES);

        const limitX = Math.ceil(stock.width / GRID_RES) - Math.ceil(Math.max(0, settings.sheetMarginRight) / GRID_RES);
        const limitY = Math.ceil(stock.height / GRID_RES) - Math.ceil(Math.max(0, settings.sheetMarginTop) / GRID_RES);

        let placedOnThisSheet = false;

        for (const item of itemsToPlace) {
            const baked = bakedParts.get(item.partId)!;

            while (item.quantity > 0) {
                let bestFit: { rot: number, x: number, y: number, mask: PartMask } | null = null;
                const rotations = [];
                if (item.constraints.allow0_180) rotations.push(0, 180);
                if (item.constraints.allow90_270) rotations.push(90, 270);
                if (rotations.length === 0) rotations.push(0);

                for (const rot of rotations) {
                    const mask = baked.masks.get(rot)!;
                    const pw = Math.ceil((mask.width + settings.partSpacingX) / GRID_RES);
                    const ph = Math.ceil((mask.height + settings.partSpacingY) / GRID_RES);

                    let tx = shelfX;
                    let ty = shelfY;

                    if (tx + pw > limitX) {
                        // New shelf
                        tx = Math.ceil(Math.max(0, settings.sheetMarginLeft) / GRID_RES);
                        ty += shelfH;
                    }

                    if (ty + ph <= limitY && tx + pw <= limitX) {
                        bestFit = { rot, x: tx, y: ty, mask };
                        break;
                    }
                }

                if (bestFit) {
                    const { rot, x, y, mask } = bestFit;
                    const pw = Math.ceil((mask.width + settings.partSpacingX) / GRID_RES);
                    const ph = Math.ceil((mask.height + settings.partSpacingY) / GRID_RES);

                    currentSheet.placedParts.push({
                        id: generateId(),
                        partId: item.partId,
                        x: x * GRID_RES + mask.ox,
                        y: y * GRID_RES + mask.oy,
                        rotation: rot
                    });

                    // Update shelf state
                    if (x === Math.ceil(Math.max(0, settings.sheetMarginLeft) / GRID_RES)) {
                        shelfX = x + pw;
                        shelfY = y;
                        shelfH = ph;
                    } else {
                        shelfX = x + pw;
                        shelfH = Math.max(shelfH, ph);
                    }

                    item.quantity--;
                    placedCount++;
                    placedOnThisSheet = true;

                    yield { 
                        sheets: [...sheets, currentSheet], 
                        progress: (placedCount / totalToPlace) * 100, 
                        status: `Лист ${sheets.length + 1}: ${currentSheet.placedParts.length} дет.` 
                    };
                } else {
                    break; // Cannot place more of this item on current sheet
                }
            }
        }

        if (placedOnThisSheet) {
            // Calculate usage stats
            let usedArea = 0;
            currentSheet.placedParts.forEach(pp => {
                const p = parts.find(x => x.id === pp.partId)!;
                usedArea += p.geometry.width * p.geometry.height;
            });
            currentSheet.usedArea = (usedArea / (stock.width * stock.height)) * 100;
            currentSheet.scrapPercentage = 100 - currentSheet.usedArea;
            currentSheet.partCount = currentSheet.placedParts.length;

            sheets.push(currentSheet);
        } else {
            // If we couldn't place anything, try the next stock sheet or stop
            stockIdx++;
            if (stockIdx >= availableStocks.length) break;
        }

        await new Promise(r => setTimeout(r, 16)); 
    }

    yield { sheets, progress: 100, status: 'Раскрой завершен' };
}
